    // channel follows the same edge.
    final decision = assessContextPressure(
      estimatedTokens: 0,
      observedTokens: 200000 - settings.reserveTokens,
      contextWindow: 200000,
      settings: settings,
    );
    expect(decision.triggered, isFalse);
    expect(decision.needsForce, isFalse);
  });

