          greaterThanOrEqualTo(previous.reserveTokens),
          reason: 'reserve monotone at window $window',
        );
        expect(
          settings.keepRecentTokens,
          greaterThanOrEqualTo(previous.keepRecentTokens),
          reason: 'keepRecent monotone at window $window',
        );
        previous = settings;
