    final smol = rolesResolver?.resolveRole(smolModelRole);
    await AutoCompactorFactory(
      session: session,
      state: child.state,
      window: window,
      settings: settings,
      sources: AutoCompactorSources(
        smolStream: smol?.stream,
        smolModel: smol?.model,
        mainStream: wiring.stream,
        mainModel: wiring.model,
