      // and past the line: the reconciled pressure must fire.
      final decision = assessContextPressure(
        estimatedTokens: 180000,
        observedTokens: 198000,
        contextWindow: 200000,
        settings: settings,
      );
      expect(decision.triggered, isTrue);
