  if (cacheSupported.isNotEmpty) _dialCacheModels = cacheSupported;
  if (windows.isNotEmpty) _modelContextWindows = windows;
  if (maxTokens.isNotEmpty) _modelMaxTokens = maxTokens;
  return ids;
}

