/// A scripted text turn whose assistant message reports usage.
List<AssistantMessageEvent> _usageTurn(
  String text, {
  int input = 0,
  int cacheRead = 0,
  int? totalTokens,
}) {
  final partial = _assistant(
    content: [TextContent(text: text)],
    input: input,
