        // when the estimate is under the trigger — these calls prove the
        // pass was forced by the observed channel.
        expect(
          wiring.stream.compactionCalls,
          greaterThanOrEqualTo(1),
          reason:
              'the observed-over-headroom channel must force the '
              'compaction pass',
