      // the trigger: no compaction call, no record.
      wiring.stream.rules.addAll({
        'quiet-observed': () => _toolTurn('c1'),
        'fat:': () =>
            _toolTurn('c2', input: 300, cacheRead: 300, totalTokens: 300),
      });
