          stream.push(StartEvent(partial: testAssistant()));
          stream.push(
            DoneEvent(
              reason: StopReason.stop,
              message: testAssistant(content: [TextContent(text: 'ok')]),
            ),
          );
          stream.end();
          return stream;
        },
      );
      return AgentCli(
        config: AgentCliConfig(
          model: testModel,
          apiKey: '[REDACTED:Sensitive Value]',
          env: env,
          sessionRoot: '/sessions',
          modelRolesResolver: resolver,
          modelsHttpClient: modelsHttpClient ?? _copilotModelsMockClient,
        ),
        io: io,
        streamFunction: fake.call,
      );
    }

    test('a chain entry on catalog defaults learns the real window', () async {
      // Copilot catalog default is 1M; the endpoint reports 128000 for
      // gpt-4.1 (see _copilotModelsMockClient).
      final fake = FakeStreamFunction([textTurn('ok')]);
      final cli = rolesCli([
        ModelRef(provider: 'copilot', modelId: 'gpt-4.1'),
      ], fake: fake);
      final run = cli.run();

      await waitForIt(
        () => io.out.toString().contains('model context window: 128000'),
        reason: 'endpoint window applied in roles mode',
      );
      io.sendLine('/exit');
      await run;

      expect(cli.agent.state.model.contextWindow, 128000);
      expect(io.out.toString(), contains('(from endpoint)'));
    });

    test('an explicitly pinned roles window wins over the endpoint', () async {
      final fake = FakeStreamFunction([textTurn('ok')]);
      final cli = rolesCli([
        ModelRef(
          provider: 'copilot',
          modelId: 'gpt-4.1',
          contextWindow: 123456,
          maxTokens: 8192,
        ),
      ], fake: fake);
      final run = cli.run();

      await waitForIt(() => io.out.toString().contains('[Model]'));
      // Give the background model-cache refresh time to (not) apply.
      await Future<void>.delayed(const Duration(milliseconds: 200));
      io.sendLine('/exit');
      await run;

      expect(cli.agent.state.model.contextWindow, 123456);
      expect(io.out.toString(), isNot(contains('(from endpoint)')));
    });

    test('an endpoint without window data gets an explicit fallback note '
        'instead of silently trusting the carried default', () async {
      // The payload lists the model but reports NO `capabilities.limits`
      // for it (the copilot-enterprise shape from the ctx-meter report):
      // the carried 1M catalog default must be flagged as unverified, not
      // trusted in silence.
      final noLimitsClient = http_testing.MockClient((request) async {
        if (request.url.host == 'api.github.com') {
          return http.Response(
            '{"token":"[REDACTED:credential]",'
            '"expires_at":9999999999,"refresh_in":1500}',
            200,
          );
        }
        if (request.url.path.endsWith('/models')) {
          return http.Response(
            '{"data":[{"id":"kimi-k2.7-code","model_picker_enabled":true,'
            '"capabilities":{"supports":{"tool_calls":true}}}]}',
            200,
          );
        }
        return http.Response('not found', 404);
      });
      final fake = FakeStreamFunction([textTurn('ok')]);
      final cli = rolesCli(
        [ModelRef(provider: 'copilot', modelId: 'kimi-k2.7-code')],
        fake: fake,
        modelsHttpClient: noLimitsClient,
      );
      final run = cli.run();

      await waitForIt(
        () => io.out.toString().contains('not reported by the endpoint'),
        reason: 'explicit fallback note for the unverified window',
      );
      io.sendLine('/exit');
      await run;

      // The carried catalog default stays — flagged, not silently trusted.
      expect(cli.agent.state.model.contextWindow, 1000000);
      expect(io.out.toString(), isNot(contains('(from endpoint)')));
    });
  });
}

