    _billChildUsage(id, child);
    await subagentManager!.update(
      id,
      status: failed ? SubagentStatus.failed : SubagentStatus.completed,
      modelId: wiring.model.id,
      error: failed ? 'schema_violation: ${structured!.error}' : null,
    );
