Now I'll write the RED test for Finding D in the 'endpoint-reported context window in roles mode' group of copilot_provider_test.dart. A mock client reporting `max_context_window_tokens: 1000` for gpt-4.1 (equal to the copilot catalog 1M) — the CONFIRMING shape. Then:

```dart
test('a CONFIRMING report verifies the registry window (gh-1742 review round 1, comment 4)', () async {
 final confirmingClient = http_testing.MockClient((request) async {
   if (request.url.host == 'api.github.com') { ... token ... }
   if (request.url.path.endsWith('/models')) {
     return http.Response('{"data":[{"id":"gpt-4.1","model_picker_enabled":true,"capabilities":{"supports":{"tool_calls":true},"limits":{"max_context_window_tokens":1000,"max_output_tokens":16384}}}]}', 200);
   }
   return http.Response('not found', 404);
 });
 final fake = FakeStreamFunction([textTurn('ok')]);
 final cli = rolesCli([ModelRef(provider: 'copilot', modelId: 'gpt-4.1')], fake: fake, modelsHttpClient: confirmingClient);
 final run = cli.run();
 await waitForIt(
   () => cli.contextWindowRegistry.isVerified(cli.agent.state.model),
   reason: 'the confirming endpoint report publishes the verification',
 );
 io.sendLine('/exit');
 await run;
 // The carried catalog value stays (a confirming report is a no-op for
 // the model) — and no "(from endpoint)" swap note prints.
 expect(cli.agent.state.model.contextWindow, 1000);
