        config: ModelRolesConfig(
          roles: {'smol': [smolRef]},
          retry: const ModelRolesRetryPolicy(retriesPerEntry: 0),
        ),
        secrets: const {'ANTHROPIC_API_KEY': 'k'},
        streamFactory: (kind, apiKey) => stream.call,
