      final wiring = _Wiring(
        registry: registry,
        rolesResolver: resolver,
        scriptedStream: stream,
      );
      // The detection lands for the SMOL identity before the spawn.
      final smol = resolver.resolveRole(smolModelRole)!;
      registry.publish(
        model: smol.model,
