  );
  return [
    StartEvent(partial: partial),
    ToolCallStartEvent(contentIndex: 0, partial: partial),
    ToolCallEndEvent(contentIndex: 0, toolCall: call, partial: partial),
    DoneEvent(reason: StopReason.toolUse, message: partial),
  ];
}

