/// A scripted turn ending in one tool call, optionally carrying usage.
List<AssistantMessageEvent> _toolTurn(
  String callId, {
  int input = 0,
  int cacheRead = 0,
  int? totalTokens,
}) {
  final call = ToolCall(id: callId, name: 'read', arguments: const {});
