String _buildSystemPrompt(TaskAgentDefinition definition, String context) {
  final systemPrompt = StringBuffer(definition.systemPrompt.trim());
  if (context.trim().isNotEmpty) {
    systemPrompt
      ..writeln()
      ..writeln()
      ..writeln('# CONTEXT')
      ..write(context.trim());
  }

