    }) {
      return ChainEntry(
        model: model,
        keyRing: ApiKeyRing(
          baseName: 'K_${model.provider}_${model.id}',
          credentials: [
            for (var i = 0; i < keyValues.length; i++)
              ApiKeyCredential(
