  Model model, {
  Duration? retryAfter,
  String error = '429: rate limit exceeded',
}) {
  final partial = _msg(model);
  return [
    StartEvent(partial: partial),
    ErrorEvent(
      reason: StopReason.error,
      error: _msg(model, stop: StopReason.error, error: error),
      retryAfter: retryAfter,
    ),
  ];
}

